Get Forms.code:
// Fetch every survey form (asset) visible to this account.
// state.data is the paginated response; state.data.results is the array of forms, each with a `uid` used as the formId.
getForms();

Get Form Submissions.code:
// Get submissions for one form.
getSubmissions(
  // 1) The form's asset uid (from the form URL or getForms()).
  $.configuration.formId,
  // 2) Options (optional).
  {
    pageSize: 1000, // max 1000 per page; paging is handled for you
  }
);

Get New Submissions Since Last Sync.code:
// Set a cursor: the last sync time saved by a previous run, or a fallback start date.
cursor($.lastSyncTime || '2026-01-01T00:00:00');

// Get submissions received since the cursor.
getSubmissions($.configuration.formId, {
  query: { _submission_time: { $gte: $.cursor } },
  sort: { _submission_time: 1 }, // oldest first
});

// Remember the newest submission time for the next run.
fn(state => {
  const last = state.data[state.data.length - 1];
  if (last) state.lastSyncTime = last._submission_time;
  return state;
});

Get Latest Submissions.code:
// Get the 50 most recent submissions.
getSubmissions($.configuration.formId, {
  sort: { _submission_time: -1 }, // newest first
  limit: 50,
});

Filter Submissions By Answer.code:
// Get submissions for one district where the household was flagged as eligible.
// Keys are the form's question names (including group paths).
getSubmissions($.configuration.formId, {
  query: {
    'household/district': $.data.district, // e.g. 'Gulu'
    'household/eligible': 'yes',
  },
});
